head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var colID = info.colID;
    var instanceIndex = rowIndex + 1;
    var inputType = WebSquare.ModelUtil.getInstanceValue("response/RES_SELECT_EMP_LIST/vector/data[" + instanceIndex + "]/TB_EMP0001_S002/INPUTTYPE/@value")
    var inputType = scwin.convertData(inputType);
    // ====================== begin of business logic ====================== 
    var returnInfo;
    switch (inputType) {
        case "radio":
            returnInfo = {
                id: "dynamic_radio_" + rowIndex + "_" + colIndex,
                inputType: "radio",
                options: {
                    groupName: "radio_" + rowIndex
                }
            }
            break;
        case "checkbox":
            returnInfo = {
                id: "dynamic_checkbox_" + rowIndex + "_" + colIndex,
                inputType: "checkbox",
                options: {}
            }
            break;
        case "button":
            returnInfo = {
                id: "dynamic_button_" + rowIndex + "_" + colIndex,
                inputType: "button",
                options: {}
            }
            break;
        case "calendar":
            returnInfo = {
                id: "dynamic_calendar_" + rowIndex + "_" + colIndex,
                inputType: "calendar",
                options: {
                    viewType: "icon"
                }
            }
            break;
        case "image":
            returnInfo = {
                id: "dynamic_image_" + rowIndex + "_" + colIndex,
                inputType: "image",
                options: {
                    imageSrc: "/T201601/A02/img.gif"
                }
            }
            break;
        case "link":
            returnInfo = {
                id: "dynamic_link_" + rowIndex + "_" + colIndex,
                inputType: "link",
                options: {}
            }
            break;
        case "select":
            returnInfo = {
                id: "dynamic_select_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    selectedData: "false",
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "response/RES_DEPT_COMBO/vector/data/COMBO",
                    label: "DNAME/@value",
                    value: "DEPTNO/@value"
                }
            }
            break;
        case "autoComplete":
            returnInfo = {
                id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
                inputType: "autoComplete",
                options: {
                    selectedData: "false",
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "response/RES_DEPT_COMBO/vector/data/COMBO",
                    label: "DNAME/@value",
                    value: "DEPTNO/@value"
                }
            }
            break;
        case "checkcombobox":
            returnInfo = {
                id: "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
                inputType: "checkcombobox",
                options: {
                    selectedData: "false",
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "response/RES_DEPT_COMBO/vector/data/COMBO",
                    label: "DNAME/@value",
                    value: "DEPTNO/@value"
                }
            }
            break;
        case "textarea":
            returnInfo = {
                id: "dynamic_textarea_" + rowIndex + "_" + colIndex,
                inputType: "textarea",
                options: {}
            }
            break;
        case "text":
            returnInfo = {
                id: "dynamic_text_" + rowIndex + "_" + colIndex,
                inputType: "text",
                options: {}
            }
            break;
        case "textImage":
            returnInfo = {
                id: "dynamic_textImage_" + rowIndex + "_" + colIndex,
                inputType: "textImage",
                options: {
                    viewType: "icon",
                    imageSrc: "/T201601/A02/alz.jpg",
                    textAlign: "center"
                }
            }
            break;
    }
    // ====================== end of business logic ====================== 
    return returnInfo;
    // 이미 생성 된 컴포넌트를 재사용하고 싶은 경우는 아이디만 리턴.
    // return  "col1_selectbox";
}
scwin.convertData = function(data) {
    data = parseInt(data);
    switch (data) {
        case 0:
            return "select";
        case 1:
            return "checkbox";
        case 2:
            return "button";
        case 3:
            return "calendar";
        case 4:
            return "image";
        case 5:
            return "link";
        case 6:
            return "select";
        case 7:
            return "autoComplete";
        case 8:
            return "checkcombobox";
        case 9:
            return "textarea";
        case 10:
            return "text";
        case 11:
            return "textImage";
    }
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.doInit = function() {
    //var v_node = WebSquare.ModelUtil.findInstanceNode("response/RES_SELECT_EMP_LIST/vector");
    //debugger;
    //grid1.setXML( v_node );
    var returnInfo1 = {
        inputType: "select",
        options: {
            selectedData: "false",
            viewType: "icon"
        },
        itemSet: {
            nodeset: "response/RES_DEPT_COMBO/vector/data/COMBO",
            label: "DNAME/@value",
            value: "DEPTNO/@value"
        },
        value: 40
    }
    //debugger;
    //grid1.setCellInputType(8, 0, returnInfo1)
    grid1.setCellData(8, 0, "aaaa")
}
scwin.onpageload = function() {
    scwin.doInit();
}

